"""Generate single-SIC-sector insolvency data pages for the data hub.

Reusable engine for any sector with a clean 3-digit SIC group in Table 1c
(the Insolvency Service's by-industry table): one config entry, one page. This
is the generic version of the bespoke Construction page in sector_pages.py —
use this for every new sector instead of hand-rolling a builder, unless the
sector needs a bespoke sub-sector breakdown like Construction has.

Leads with the CURRENT picture (year-to-date vs the same months last year,
rolling 12 months, latest single month) rather than the last full calendar
year — Table 1c publishes the industry breakdown monthly (through the latest
headline month), not quarterly as earlier drafts of this page claimed; only
the supplementary procedure-split tables are quarterly. The full-year annual
total is still shown, but as trailing context, not the headline.

To stay visually consistent with the rest of the family, pages reuse the
flagship's shared CSS/chrome (masthead, source strip, methodology, final CTA)
and the shared line-chart engine.

Data: data/insolvency-statistics/sector_series.json "groups" (all ~272
3-digit SIC groups, annual since 2016 + monthly since 2023; built by
scripts/datahub/parse_sector_series.py) + release_metadata.json.

Usage:
    python scripts/datahub/pages/sic_group_stats.py                            # all
    python scripts/datahub/pages/sic_group_stats.py furniture-insolvency-statistics
"""

from __future__ import annotations

import json
import sys
from pathlib import Path
from textwrap import dedent

ROOT = Path(__file__).resolve().parents[3]
SCRIPTS = ROOT / "scripts"
sys.path.insert(0, str(SCRIPTS))

from build_insolvency_dashboard import (  # noqa: E402
    DASHBOARD_CSS, masthead_block, srcstrip_block, methodology_block, final_cta_block,
)
from build_insolvency_charts import build_line_chart, format_number  # noqa: E402

DATA = ROOT / "data" / "insolvency-statistics"
DRAFTS = ROOT / "drafts"
SENTINEL = ("<!-- CD-NO-AUTOEDIT: data_reference page generated by "
            "scripts/datahub/pages/sic_group_stats.py. "
            "Internal-link and article-rewrite pipelines must skip this file. -->")

MONTH_FULL = ["January", "February", "March", "April", "May", "June",
              "July", "August", "September", "October", "November", "December"]


def month_full(period: str) -> str:
    """'2026-05' -> 'May 2026'."""
    y, m = period.split("-")
    return f"{MONTH_FULL[int(m) - 1]} {y}"


# Static, number-free copy per sector. Live figures are computed at build time
# from sector_series.json "groups" by sic_code. Add a new sector by adding an
# entry here + a WP page (scripts/datahub/create_staging_pages.py) + the
# cc_builder/mu-plugin registration (see docs/data-hub/page-specs.md).
#
# "pressure" entries are editorial judgement (general, well-established sector
# economics), NOT sourced statistics — do not add a specific number to one of
# these unless it has been verified against a primary source and wired through
# figures()/sector_fact() like every other number on the page. A plausible
# invented figure is worse than no figure.
